CREATE   VIEW [EventBrite].[vwEvent]
AS
SELECT 
	CAST(ev.[Event_Id] AS NVARCHAR(20)) + '_' + CAST(ev.[Organization_Id] AS NVARCHAR(20)) AS [EventKey]
	,CAST(ev.[Category_Id] AS NVARCHAR(20)) + '_' + CAST(ev.[Organization_Id] AS NVARCHAR(20)) AS [CategoryKey]
	,CAST(ev.[SubCategory_Id] AS NVARCHAR(20)) + '_' + CAST(ev.[Organization_Id] AS NVARCHAR(20)) AS [SubCategoryKey]
	,CAST(ev.[Venue_Id] AS NVARCHAR(20)) + '_' + CAST(ev.[Organization_Id] AS NVARCHAR(20)) AS [VenueKey]
	,CAST(CONVERT(VARCHAR(10), ev.[StartTime], 112) AS BIGINT) AS [StartDateKey]
	,ev.[Event_Id] AS [Event Id]
	,ev.[Link_Id]
	,CAST(ev.[createdon] AS DATE) AS [Createdon]
	,CAST(ev.[modifiedon] AS DATE) AS [Modifiedon]
	,ev.[Status]
	,ev.[Capacity]
	,ev.[Category_Id]
	,ev.[Currency_Code]
	,ev.[Description] AS [Event Description]
	,CAST(ev.[StartTime] AS DATE) AS [Start Date]
	,CAST(ev.[Starttime] AS TIME) AS [Start Time]
	,CAST(ev.[EndTime] AS DATE) AS [End Date]
	,CAST(ev.[EndTime] AS TIME) AS [End Time]
	,IIF(ev.[InviteOnly]=1, 'Yes', 'No') AS [Invite Only]
	,IIF(ev.[Is_Externally_Ticketed] = 1, 'Yes', 'No') AS [Externally Ticketed]
	,IIF(ev.[IsFree] = 1, 'Yes', 'No') AS [Is Free]
	,IIF(ev.[islocked] = 1, 'Yes', 'No') AS [Is Locked]
	,IIF(ev.[is_Reserved_Seating]= 1, 'Yes', 'No') AS [Is Reserved Seating]
	,IIF(ev.[isSeries]= 1, 'Yes', 'No') AS [Is Series]
	,IIF(ev.[is_Series_Parent]= 1, 'Yes', 'No') AS [Is Series Parent]
	,IIF(ev.[Listed]= 1, 'Yes', 'No') AS [Is Listed]
	,ev.[Name] AS [Event Name]
	,IIF(ev.[Online_Event] = 1, 'Yes', 'No') AS [Is Online Event]
	,ev.[Organization_Id]
	,ev.[Organizer_Id]
	,ev.[SubCategory_Id]
	,ev.[Total_Time_Limit] AS [Total Time Limit]
	,ev.[Venue_Id]
FROM [EventBrite].[tblEvent] ev
